at::Tensor matmul_sigmoid_sum_custom_impl_npu(const at::Tensor& x,
                                              const at::Tensor& weight,
                                              const at::Tensor& bias) {
    // Output is [B, 1]
    auto sizes = x.sizes();
    TORCH_CHECK(sizes.size() == 2, "x should be 2D [B, K]");
    at::Tensor result = at::empty({sizes[0], 1}, x.options());
    EXEC_NPU_CMD(aclnnMatmulSigmoidSumCustom, x, weight, bias, result);
    return result;
}

